describe('SidebarMenuButton', () => {
  it('renders [data-slot="sidebar-menu-button"] with its classes', () => {
    expect(classesOfSidebarMenuButton()).toEqual(
      expect.arrayContaining([
        styles.sidebarMenuButton,
        styles.sidebarMenuButtonVariantDefault,
        styles.sidebarMenuButtonSizeDefault,
      ]),
    )
  })

  it.each([
    ['default', styles.sidebarMenuButtonVariantDefault],
    ['outline', styles.sidebarMenuButtonVariantOutline],
  ] as const)('variant %s applies its class', (value, className) => {
    expect(classesOfSidebarMenuButton({ variant: value })).toContain(className)
  })

  it.each([
    ['default', styles.sidebarMenuButtonSizeDefault],
    ['sm', styles.sidebarMenuButtonSizeSm],
    ['lg', styles.sidebarMenuButtonSizeLg],
  ] as const)('size %s applies its class', (value, className) => {
    expect(classesOfSidebarMenuButton({ size: value })).toContain(className)
  })

  it('applies no group class for a null group', () => {
    const classes = classesOfSidebarMenuButton({ variant: null, size: null })
    expect(classes).toContain(styles.sidebarMenuButton)
    for (const className of [
      styles.sidebarMenuButtonVariantDefault,
      styles.sidebarMenuButtonVariantOutline,
      styles.sidebarMenuButtonSizeDefault,
      styles.sidebarMenuButtonSizeSm,
      styles.sidebarMenuButtonSizeLg,
    ]) {
      expect(classes).not.toContain(className)
    }
  })

  it('renders the same with isActive=false passed explicitly', () => {
    expect(attributesOfSidebarMenuButton({ isActive: false })).toEqual(
      attributesOfSidebarMenuButton(),
    )
  })

  it('renders differently with isActive=true', () => {
    expect(htmlOfSidebarMenuButton({ isActive: true })).not.toBe(htmlOfSidebarMenuButton())
  })

  it('throws outside its root: useSidebar must be used within a SidebarProvider.', () => {
    cleanup()
    expect(() => render(<SidebarMenuButton />)).toThrow(
      'useSidebar must be used within a SidebarProvider.',
    )
  })

  it('appends a consumer className last', () => {
    renderSidebarMenuButton({ className: 'consumer' })
    const element = document.querySelector('.consumer')
    expect(element?.getAttribute('class')?.split(' ').at(-1)).toBe('consumer')
  })

  it("renders as upstream's example uses it (2)", () => {
    cleanup()
    render(
      <SidebarProvider defaultOpen>
        <Sidebar>
          <SidebarContent>
            <SidebarGroup>
              <SidebarGroupContent>
                <SidebarMenu>
                  <SidebarMenuItem>
                    <SidebarMenuButton data-subject>SidebarMenuButton</SidebarMenuButton>
                  </SidebarMenuItem>
                </SidebarMenu>
              </SidebarGroupContent>
            </SidebarGroup>
          </SidebarContent>
        </Sidebar>
      </SidebarProvider>,
    )
    expect(document.querySelector('[data-subject]')).not.toBeNull()
  })
})

